CREATE TABLE "PosSale" ("id" UUID NOT NULL,"tenantId" UUID NOT NULL,"storeId" UUID NOT NULL,"tillId" TEXT NOT NULL,"cashierId" TEXT NOT NULL,"receiptNo" TEXT NOT NULL,"idempotencyKey" TEXT NOT NULL,"total" DECIMAL(18,2) NOT NULL,"status" TEXT NOT NULL DEFAULT 'COMPLETED',"soldAt" TIMESTAMP(3) NOT NULL,"receivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PosSale_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PosSaleLine" ("id" UUID NOT NULL,"saleId" UUID NOT NULL,"productId" UUID NOT NULL,"itemCode" TEXT NOT NULL,"barcode" TEXT,"name" TEXT NOT NULL,"quantity" DECIMAL(18,3) NOT NULL,"unitPrice" DECIMAL(18,2) NOT NULL,"vatRate" DECIMAL(8,4) NOT NULL,"lineTotal" DECIMAL(18,2) NOT NULL,CONSTRAINT "PosSaleLine_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PosPayment" ("id" UUID NOT NULL,"saleId" UUID NOT NULL,"method" TEXT NOT NULL,"amount" DECIMAL(18,2) NOT NULL,"reference" TEXT,CONSTRAINT "PosPayment_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "PosSale_tenantId_idempotencyKey_key" ON "PosSale"("tenantId","idempotencyKey");CREATE UNIQUE INDEX "PosSale_tenantId_receiptNo_key" ON "PosSale"("tenantId","receiptNo");CREATE INDEX "PosSale_tenantId_storeId_soldAt_idx" ON "PosSale"("tenantId","storeId","soldAt");CREATE INDEX "PosSaleLine_saleId_idx" ON "PosSaleLine"("saleId");CREATE INDEX "PosSaleLine_productId_idx" ON "PosSaleLine"("productId");CREATE INDEX "PosPayment_saleId_idx" ON "PosPayment"("saleId");
ALTER TABLE "PosSale" ADD CONSTRAINT "PosSale_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "PosSale" ADD CONSTRAINT "PosSale_storeId_tenantId_fkey" FOREIGN KEY ("storeId","tenantId") REFERENCES "Store"("id","tenantId") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "PosSaleLine" ADD CONSTRAINT "PosSaleLine_saleId_fkey" FOREIGN KEY ("saleId") REFERENCES "PosSale"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "PosSaleLine" ADD CONSTRAINT "PosSaleLine_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "PosPayment" ADD CONSTRAINT "PosPayment_saleId_fkey" FOREIGN KEY ("saleId") REFERENCES "PosSale"("id") ON DELETE RESTRICT ON UPDATE CASCADE;